import { z } from 'zod';
import { BoundaryErrorCode } from './error-codes.js';
import { Severity } from './enums.js';
import { GoalThresholdFrame } from '../graph.js';
// Narrowed subset of ActionType for graph-edit operations. Used by the
// GraphPatchBlock `operation` field so semantic-garbage constructions like
// `GraphPatchBlock{ operation: 'run_analysis' }` fail at parse time.
// Kept inline here because GraphPatchBlock is the only consumer; if a future
// slice needs the same subset elsewhere, lift to /boundary/enums.ts.
// Subset-ness relative to ActionType is verified by a runtime test in the
// schemas test suite (drift guard).
const GraphEditOperationSchema = z.enum([
    'set_factor_value',
    'add_constraint',
    'adjust_edge_strength',
]);
// Text block — carries free-form assistant content.
export const TextBlockSchema = z.object({
    type: z.literal('text'),
    content: z.string(),
}).strict();
// Error block — user-visible failure, keyed by stable BoundaryErrorCode.
export const ErrorBlockSchema = z.object({
    type: z.literal('error'),
    error_code: BoundaryErrorCode,
    severity: Severity,
    details: z.object({}).passthrough().optional(),
}).strict();
// ----------------------------------------------------------------------------
// V5 handler-result blocks (0.5.0)
//
// Discriminated by `type`. Additive — new block types join the BlockSchema
// union without breaking A0/A1/A2 consumers.
//
// Content-shape is intentionally permissive: each block declares its common
// rendering fields and leaves handler-specific enrichment under an `enrichment`
// record so that D1/D2 tranches can extend without another schema bump. The
// content assertions (rev-2 revision 6) live in CEE tests, not in schemas.
// ----------------------------------------------------------------------------
// AnalysisResultBlock — emitted by run_analysis. Threads PLoT enrichment
// (factor_sensitivity, flip_thresholds, conditional_probabilities, edge_e_values,
// m1_coaching) through the `enrichment` record.
//
// v0.14.0: the enrichment record now has a typed opt-in envelope —
// `AnalysisEnrichmentSchema` in ./enrichment.ts. The transport field below
// deliberately STAYS `z.record(z.unknown())` (behaviour-preserving for every
// pinned consumer); consumers validate/type via
// `AnalysisEnrichmentSchema.safeParse(block.enrichment)`.
export const AnalysisResultBlockSchema = z.object({
    type: z.literal('analysis_result'),
    summary: z.string(),
    leading_option_id: z.string().nullable(),
    win_probabilities: z.record(z.string(), z.number()).optional(),
    enrichment: z.record(z.string(), z.unknown()).optional(),
    // 0.22.0 additive (S1 — graph-identity handshake). The canonical hash of the
    // graph state this analysis result was COMPUTED AGAINST (the
    // CANONICAL_GRAPH_HASH_KEEP_LIST floor — see ./graph-hash-contract.ts). A
    // client compares it against its current canonical hash to decide freshness;
    // a mismatch is a GRAPH_DIVERGED divergence, never a silent stale render.
    // Optional so pinned consumers are unaffected until re-vendored; absent = no
    // computed-against assertion.
    computed_against_hash: z.string().min(1).optional(),
}).strict();
// GraphPatchBlock — emitted by D1 handlers (set_factor_value, add_constraint,
// adjust_edge_strength). `status: 'noop'` signals the D1 NOOP suppression path
// (rev-2 revision 5).
export const GraphPatchBlockSchema = z.object({
    type: z.literal('graph_patch'),
    status: z.enum(['applied', 'noop']),
    operation: GraphEditOperationSchema,
    target_id: z.string().min(1),
    before: z.record(z.string(), z.unknown()).nullable(),
    after: z.record(z.string(), z.unknown()).nullable(),
}).strict();
// ExplanationBlock — emitted by explain_result.
export const ExplanationBlockSchema = z.object({
    type: z.literal('explanation'),
    narrative: z.string(),
    referenced_option_ids: z.array(z.string()),
    enrichment: z.record(z.string(), z.unknown()).optional(),
}).strict();
// ComparisonBlock — emitted by compare_options. Tests assert ≥2 distinct
// options when analysis has them; schema permits ≥1 so edge cases (degenerate
// single-option analyses) do not blow up at validation time.
export const ComparisonBlockSchema = z.object({
    type: z.literal('comparison'),
    options: z.array(z.object({
        option_id: z.string().min(1),
        label: z.string().min(1),
        win_probability: z.number().optional(),
        attributes: z.record(z.string(), z.unknown()).optional(),
    }).strict()).min(1),
    narrative: z.string().optional(),
}).strict();
// FlipAnalysisBlock — emitted by what_would_flip. `flip_scenarios` may be
// empty when no fragile edges or thresholds exist.
export const FlipAnalysisBlockSchema = z.object({
    type: z.literal('flip_analysis'),
    narrative: z.string(),
    flip_scenarios: z.array(z.object({
        factor_id: z.string().min(1),
        current_value: z.number().nullable(),
        flip_threshold: z.number().nullable(),
        from_option_id: z.string().nullable(),
        to_option_id: z.string().nullable(),
        fragile: z.boolean(),
    }).strict()),
    enrichment: z.record(z.string(), z.unknown()).optional(),
}).strict();
// DraftGoalConstraint — a hard constraint extracted from the user's brief at
// DRAFT time and carried on the draft_graph block (v0.18.0).
//
// ⚠ NOT THE SAME TYPE AS `LegacyGoalConstraintStubSchema` in `./run.ts`.
// These are two different payloads, and conflating them is the exact
// same-named-twin defect that has bitten this programme before:
//
//   ./run.ts LegacyGoalConstraintStubSchema — a never-exercised A0 stub
//     (formerly misnamed `GoalConstraintSchema`, which mislabelled it as the
//     compute-seam constraint; no service imports it). Identity `id`,
//     five-way `bound` enum ('lt'|'lte'|'gt'|'gte'|'eq'), no node binding,
//     no provenance. `.strict()`.
//   THIS schema                             — the DRAFTING-time EXTRACTION
//     (CEE -> UI). Identity `constraint_id`, node-bound via `node_id`,
//     two-way ASCII `operator` ('>='|'<='), and carries extraction
//     provenance the compute path has no concept of (source_quote /
//     confidence / provenance).
//
// The LIVE compute-seam constraint is PLoT's own `GoalConstraint`
// (plot-lite `src/types/engine-v3.ts`, `constraint_id`/`node_id`/ASCII
// `operator` — the shape THIS schema mirrors); the analysis-result side of
// that seam is published as JSON-Schema from `src/boundary/enrichment.ts`.
// Neither schema here is a superset of the other; they are kept distinct and
// DIFFERENTLY NAMED.
//
// Field-level validators mirror CEE's producer schema (`src/schemas/assist.ts`
// `GoalConstraintSchema`) exactly. That is safe rather than risky: CEE's Stage-4
// structural-parse substep already runs `DraftGraphOutput.parse()` — which
// embeds those same validators — over this very array and hard-fails the turn
// (400 CEE_GRAPH_INVALID) before egress, so anything that reaches the wire has
// already satisfied them. Re-declaring them here adds no new rejection surface.
//
// `.passthrough()` — deliberate, and the one place this schema does NOT mirror
// CEE. CEE's regex path emits `provenance_unit_normalised` (from the
// percent->fraction rewrite in `normaliseConstraintUnits`), which is absent from
// CEE's own schema; its structural-parse is validation-only (the parsed result
// is discarded, so nothing is stripped) and the key reaches the wire. A
// `.strict()` element would turn every percent constraint into an
// EGRESS_CONTRACT_VIOLATION — the precise failure mode this change exists to
// remove. Passthrough is also this package's documented default (README).
export const DraftGoalConstraintSchema = z.object({
    /** Unique constraint identifier (CEE: `constraint_<node_id>_<min|max>`). */
    constraint_id: z.string().min(1),
    /**
     * Target node this constraint binds to. CEE drops any constraint whose
     * node_id does not match a node in the drafted graph, so a value here is
     * guaranteed to resolve against the sibling `nodes` array.
     */
    node_id: z.string().min(1),
    /** ASCII only — CEE normalises away '<', '>' and the Unicode forms. */
    operator: z.enum(['>=', '<=']),
    /** Threshold in the user's units; PLoT normalises downstream. */
    value: z.number(),
    /** Human-readable label, e.g. 'First-year budget cap'. */
    label: z.string().optional(),
    /** Unit if known ('£', '%', 'fraction', 'hours', ...). */
    unit: z.string().optional(),
    /**
     * Verbatim span from the brief that produced this constraint. CEE truncates
     * to 200 chars at extraction; not re-capped here — the cap is CEE ingestion
     * policy, not a wire invariant, and this contract must never be the thing
     * that fails a draft response.
     */
    source_quote: z.string().optional(),
    /** Extraction confidence (0-1). Regex path: 0.85 explicit / 0.6 inferred. */
    confidence: z.number().min(0).max(1).optional(),
    /** How the constraint was obtained — drives UI provenance display. */
    provenance: z.enum(['explicit', 'inferred', 'proxy']).optional(),
    /** Present only for temporal ('by <date>') constraints. */
    deadline_metadata: z.object({
        deadline_date: z.string().optional(),
        reference_date: z.string().optional(),
        assumed_reference_date: z.boolean().optional(),
    }).passthrough().optional(),
    /**
     * Audit trail for the percent->fraction rewrite. Declared (rather than left
     * to passthrough) so the value is typed for consumers and cannot be silently
     * dropped by a future stricter pin.
     */
    provenance_unit_normalised: z.object({
        rule: z.string(),
        original_value: z.number(),
        original_unit: z.string(),
    }).passthrough().optional(),
    /**
     * 0.38.0 additive (ROADMAP 2.266 schemas-train half; reinforced by 2.298).
     * The FRAME `value` is stated in. Reuses the canonical `GoalThresholdFrame`
     * enum (0.31.0) — one frame vocabulary, two attestation sites; see its block
     * comment in `src/graph.ts` for the full contract. Per limit:
     *   · `'level'`      — an absolute level on the metric's own scale;
     *   · `'delta'`      — LEGACY: already in the engine samples' own frame (a
     *                      change from the MODEL'S ORIGIN, not from today). No
     *                      new writers; existing rows are not migrated in bulk;
     *   · `'change_abs'` — 0.61.0 (R1): a change from today, `value` stated on
     *                      the scale a `level` value on this row would use
     *                      ("2 points higher than now" is 2; "no worse" is 0);
     *   · `'change_rel'` — 0.61.0 (R1): a relative change from today, `value` a
     *                      fraction ("cut by 20%" is -0.20), based on the TARGET
     *                      NODE's own `observed_state.baseline` (no per-limit
     *                      base — see below).
     * 0.61.0 changes nothing here but the shared enum: the two values arrive
     * because this field IS that instance (identity-pinned in
     * tests/boundary/draft-goal-constraint-value-frame.test.ts). A limit's
     * frame is already an analysis-hash input, because `goal_constraints` is
     * hashed whole (AIQ #72 5871459631).
     *
     * WHY: `goal_constraints[].value` carries the SAME unattested
     * level-vs-delta problem that made the goal probability a structural zero
     * before 0.31.0 — ISL evaluates constraints against change-from-baseline
     * samples, CEE mints values as absolute levels, nobody converts
     * (witness-2258: `goal_fit 0.0054` where the honest answer was ~0.55).
     * Two honesty gates are suppressed pending exactly this attestation
     * (PLoT's auto-synthesis 'level' refusal; ISL's frame-blind constraint
     * check refusing rather than converting).
     *
     * THIS FIELD IS THE PRECONDITION FOR REINSTATING THOSE GATES, NOT THE
     * DELIVERY. Producer adoption rides separate trains: CEE stamps it as a
     * CODE CONSTANT at its constraint mint sites (never LLM-derivable — the
     * frame is a property of the minting arithmetic, exactly as for
     * `goal_threshold_frame`; R1 S4 moves CEE to a typed drafter frame — see
     * `GoalThresholdFrame`), PLoT forwards it, ISL declares it (0.38.0 said
     * "today `GoalConstraint` has `extra: 'ignore'` and silently drops it";
     * ISL staging `b2215d36` declares `value_frame: Optional[Literal["level",
     * "delta"]]` at `src/models/robustness_v2.py:815`, which must widen before
     * any producer stamps a 0.61.0 value — an unknown literal is a 422) and owns
     * the conversion at its comparison site, holding the `observed_state`
     * baselines. No per-constraint baseline member is added: the baseline is
     * a property of the TARGET NODE (`observed_state.baseline`, plus CEE's
     * enricher-minted `goal_baseline`/`goal_baseline_raw` riding NodeV3
     * passthrough) — copying it per-constraint would create a second source
     * of truth that can diverge from the node's.
     *
     * FAILURE SEMANTICS — FAIL CLOSED. Absence means UNATTESTED: consumers
     * MUST NOT compute joint-goal figures from an unattested constraint value,
     * and MUST NOT default this field — a defaulted frame is a manufactured
     * attestation, the exact fabrication class 2.258/2.266 exist to kill.
     */
    value_frame: GoalThresholdFrame.optional(),
}).passthrough();
// DraftGraphBlock — emitted by the draft_graph pre-Sonnet dispatcher (v0.8.0)
// and, from 0.43.0, used as the canonical committed-graph receipt after a
// transactional mutation. Carries the full graph inline so the UI can apply
// the exact committed state without a Supabase re-fetch. nodes/edges/options
// are permissive arrays (z.unknown() elements) so CEE-format shapes pass
// without a schema bump when their nested fields evolve. node_count/edge_count
// are receipt metadata derived from the SAME node/edge arrays.
//
// `.strict()` is retained deliberately. It is why `goal_constraints` had to be
// declared here before CEE could emit it (an undeclared key produces
// `unrecognized_keys`, which CEE's validateEgress turns into a whole-response
// EGRESS_CONTRACT_VIOLATION fallback) — the fix for a dropped field at this
// seam is to DECLARE it, never to loosen the block to passthrough.
export const DraftGraphBlockSchema = z.object({
    type: z.literal('draft_graph'),
    nodes: z.array(z.unknown()),
    edges: z.array(z.unknown()),
    node_count: z.number().int().min(0),
    edge_count: z.number().int().min(0),
    /**
     * Canonical option records, including status/baseline and the complete
     * intervention tuple. Added in 0.43.0 as additive-optional so pre-0.43.0
     * four-field draft blocks still parse unchanged.
     *
     * ABSENCE SEMANTICS ARE LOAD-BEARING. On a legacy partial block, omission
     * means "this producer made no complete options attestation"; it is NOT a
     * request to delete options. A canonical transactional producer MUST own
     * this key and emit `[]` to attest that the committed graph has no options.
     */
    options: z.array(z.unknown()).optional(),
    /**
     * Identity of the committed goal node. Added in 0.43.0 as
     * additive-optional for legacy-reader compatibility.
     *
     * Canonical absence is explicitly `null`: it means the producer inspected
     * the committed graph and attests that it has no goal. Omission means only
     * that a legacy/partial producer did not carry this hash field. Consumers
     * MUST NOT interpret omission as deletion, and an empty string is never a
     * goal identity.
     */
    goal_node_id: z.string().min(1).nullable().optional(),
    /**
     * Hard constraints extracted from the brief (v0.18.0, additive/optional).
     * Constraints are METADATA, not causal structure — CEE deliberately does not
     * emit them as graph nodes or edges, so this array is the ONLY channel by
     * which a user's stated constraint reaches the client.
     *
     * 0.43.0 tightens the producer doctrine without breaking old readers:
     * omission on a legacy partial block means "not attested", never "clear the
     * constraints". A canonical transactional producer MUST own this key and
     * emit `[]` to attest that the committed graph has no constraints.
     */
    goal_constraints: z.array(DraftGoalConstraintSchema).optional(),
}).strict();
/**
 * The strict producer contract for a canonical committed-graph receipt.
 *
 * `DraftGraphBlockSchema` keeps the three analysis-state fields optional so
 * legacy draft responses remain readable. Transactional producers use THIS
 * derived schema: all five canonical graph-hash carrier fields are required,
 * including own-key `options: []`, `goal_node_id: null`, and
 * `goal_constraints: []` for explicit absence. It intentionally contains no
 * readiness member; whole-status readiness has a separate single authority.
 */
const CanonicalCommittedGraphBlockObjectSchema = DraftGraphBlockSchema.extend({
    options: z.array(z.unknown()),
    goal_node_id: z.string().min(1).nullable(),
    goal_constraints: z.array(DraftGoalConstraintSchema),
}).strict();
function enforceCanonicalReceiptCounts(value, ctx) {
    if (value.node_count !== value.nodes.length) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['node_count'],
            message: 'must equal nodes.length for a canonical committed receipt',
        });
    }
    if (value.edge_count !== value.edges.length) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['edge_count'],
            message: 'must equal edges.length for a canonical committed receipt',
        });
    }
}
export const CanonicalCommittedGraphBlockSchema = CanonicalCommittedGraphBlockObjectSchema.superRefine(enforceCanonicalReceiptCounts);
/** The top-level `OlumiResponse.draft_graph` form (block discriminator omitted). */
export const CanonicalCommittedGraphReceiptSchema = CanonicalCommittedGraphBlockObjectSchema.omit({
    type: true,
})
    .strict()
    .superRefine(enforceCanonicalReceiptCounts);
// ----------------------------------------------------------------------------
// V5 Phase 3 block types — Analysis tab data contract v1.3
//
// Source of truth: `Docs/v5/v5-analysis-tab-data-contract-v1_3.md` in the CEE
// repo (committed via PR #177, SHA-256
// 24905122025585da88ba3f9423bc8300ff5985736984814fce9fac334dd1df69).
//
// These schemas encode the contract verbatim. Field shapes, unions, and
// optionality match §0–§1.4. Do not deviate without a contract amendment
// (§8 change process).
//
// Scope of common metadata (§0): MANDATORY for ReviewCardBlock,
// CoachingBlock, EvidenceBlock, ExerciseBlock. Existing FactBlock /
// GraphPatchBlock remain unchanged unless separately versioned.
// ----------------------------------------------------------------------------
// §0.4 — Action intent strict union (15 values). New intents require a
// contract update.
export const ActionIntent = z.enum([
    'explain_driver',
    'explain_result',
    'what_would_flip',
    'rerun_analysis',
    'gather_evidence',
    'create_decision_brief',
    'add_option',
    'add_risk',
    'confirm_factor',
    'edit_factor',
    'compare_options',
    'run_pre_mortem',
    'run_outside_view',
    'run_devils_advocacy',
    'start_guided_chat',
]);
// §0.1 — target_refs kind union (7 values). Strict; no string escape hatch.
export const TargetRefKind = z.enum([
    'factor',
    'option',
    'edge',
    'goal',
    'risk',
    'constraint',
    'outcome',
]);
// §0.1 — Target reference. IDs allowed in this structured field; must NOT
// appear in `title`, `body`, `action_label`, or any other user-facing
// text field (composer-layer enforcement).
export const TargetRefSchema = z.object({
    id: z.string().min(1),
    label: z.string().min(1),
    kind: TargetRefKind,
}).strict();
// §0 — Freshness verdict for Phase 3 blocks. Distinct from the
// analysis-ready freshness used elsewhere ('fresh' | 'stale' | 'unknown'
// | 'none'): Phase 3 block freshness uses `pending` while generation is
// in flight and `failed` when the generator threw.
export const Phase3BlockFreshness = z.enum([
    'fresh',
    'stale',
    'pending',
    'failed',
]);
// §1.1 / §1.3 — Block-level severity for user-facing review / evidence
// rendering. DISTINCT from the existing `Severity` (`info` / `warn` /
// `error`) used for ErrorBlock / system telemetry. Phase 3 blocks use
// product-tier severities that map to visual treatment in the Analysis
// tab.
export const Phase3BlockSeverity = z.enum([
    'info',
    'warning',
    'critical',
]);
// ----------------------------------------------------------------------------
// Guidance signals (0.19.0) — wave-2 producer fields, UI-SEM-085.
//
// THE `priority_rank` CONTRACT, stated once, authoritatively (this is the
// answer to the UI's §3.2 ask — consumers were inverting it as
// `100 - priority_rank`, which is WRONG):
//
//   * `priority_rank` is an ASCENDING ordinal: LOWER = shown FIRST. It is a
//     display order, not a merit score.
//   * Its range is the positive integers, UNBOUNDED. It is NOT a 0–100 scale;
//     never invert it against 100 (ranks ≥ 100 are routine).
//   * The band prefix IS meaningful — it encodes the producer's block-class
//     ordering, not a score: 1–9 lifecycle-urgent (e.g. the stale-rerun
//     nudge at rank 1); 10–99 analysis review cards (curated per-kind bands:
//     narrative 10, pre-mortem 20, flip 30+, bias 40+, robustness 50,
//     evidence-priority 60, assumption 70+, scenario-context 80+);
//     100–199 coaching; 200+ calibration prompts / exercises.
//   * Ranks are unique only WITHIN a producing band, not globally: a
//     consumer sorting a mixed guidance feed sorts ascending and treats
//     equal ranks as producer-order ties.
//
// `GuidanceCategory` + `priority` (both OPTIONAL, additive 0.19.0) are the
// producer-owned severity/urgency signals the UI previously invented
// client-side (UI-SEM-085: measured 10/10 blocks with UI-authored
// `category`). Semantics:
//
//   * `category` — the canonical four-value guidance class the Strengthen
//     surface budgets and filters on. Code-keyed: a consumer maps each value
//     to its OWN display copy (same doctrine as HeldProposalReasonCode).
//   * `priority` — a COARSE 0–100 urgency score for cross-surface budgeting,
//     HIGHER = more urgent. It is intentionally band-granular (derived 1:1
//     from `category` by the producer): ties are expected and normal. It is
//     NOT a display order — to order a feed, sort by `priority_rank`
//     ascending; use `priority`/`category` to budget, filter, and style.
//
// Consumers MUST tolerate absence (fail closed to their existing unranked
// treatment): blocks produced before 0.19.0, or by producers that have not
// re-vendored, will not carry these fields.
export const GuidanceCategory = z.enum([
    'must_fix',
    'should_fix',
    'could_fix',
    'technique',
]);
// ----------------------------------------------------------------------------
// Guidance signal provenance (0.20.0) — ROADMAP 1.120 residual, UI-SEM-085.
//
// `signal_code` + `signal` (both OPTIONAL, additive 0.20.0, declared on the
// same four guidance-bearing blocks as 0.19.0's `category` / `priority`).
// They finish the UI-SEM-085 repair: on the live path the UI was measured
// inventing `signal_code` from `block.type` on 10/10 guidance blocks
// ('review_card' / 'coaching' — block TYPES, not signal codes — which is why
// nothing ever matched a real code such as MISSING_BASE_RATE, and why
// 'discuss'-actionability is still a client-side heuristic).
//
//   * `signal_code` — a STABLE machine-readable code naming the producer
//     signal that generated this item (e.g. `MISSING_BASE_RATE`, a
//     readiness-blocker code, the stale-rerun nudge). DISTINCT from
//     `signal_id`: `signal_id` is the per-instance DEDUPE identity;
//     `signal_code` is the signal's CLASS, shared by every instance the same
//     detector produces. Consumers key behaviour (actionability, icons,
//     grouping) off this code and fail closed to their existing generic
//     treatment on codes they do not recognise. Typed as an open non-empty
//     string, NOT a closed enum: the vocabulary is producer-owned (CEE's
//     signal registry) and evolves without a schema bump — a closed enum
//     here would be a hand-maintained mirror of a registry this package
//     does not own (the known drift defect). Casing convention (signed off
//     by the UI workstream, 20 Jul 2026): SCREAMING_SNAKE_CASE, per the
//     platform's code-keyed families (MISSING_BASE_RATE, GRAPH_TOO_LARGE,
//     the PLoT critique codes) — it also visually distinguishes CODES from
//     lower_snake field names, which serves the signal_code ≠ signal_id
//     distinction. Doc-level convention only: the schema deliberately does
//     NOT validate casing (the registry stays producer-owned).
//   * `signal` — a SHORT producer-authored display line stating what
//     triggered this item, rendered per-item by guidance surfaces (the
//     Strengthen panel's signal line is UI-derived today). Display-safe by
//     the same rules as `title`: no internal ids, no doctrine prose.
//     Bounded short (a caption, not a narrative — same treatment as
//     UiDirectiveBlock's `note`). The 140 cap is a WIRE BOUND, not a layout
//     contract: consumers clamp visually to their own surfaces, and no
//     future card redesign should require a schema change here.
//
// Consumers MUST tolerate absence (fail closed): blocks produced before
// 0.20.0, or by producers that have not re-vendored, will not carry them.
const GUIDANCE_SIGNAL_LINE_MAX = 140;
// §0.2 — Copy-length constraints. CEE enforces at the composer layer;
// schema-side enforcement is defence-in-depth so a composer bug surfaces
// as a Zod validation failure at the boundary rather than being silently
// truncated downstream by the Analysis tab.
const PHASE3_TITLE_MAX = 80;
const PHASE3_BODY_MAX = 300;
const PHASE3_ACTION_LABEL_MAX = 40;
// 0.31.0 — bound for `action_prompt` (see CoachingBlockSchema). DERIVED, not
// picked: `action_label` is a BUTTON CAPTION and takes the caption bound (40),
// whereas `action_prompt` is producer-authored PROSE that becomes a turn, so it
// takes this file's existing bound for producer-authored prose on these same
// blocks — PHASE3_BODY_MAX. It is written as its own named constant rather
// than reusing `PHASE3_BODY_MAX` directly because the two are equal today by
// derivation, not by definition: retuning body copy must not silently retune
// what a chip is allowed to say.
const PHASE3_ACTION_PROMPT_MAX = 300;
/**
 * 0.39.0 — the DSK bundle's declared evidence-strength union, extracted as
 * ONE shared instance now that two provenance shapes carry it
 * (`DskClaimProvenanceSchema` below and 0.37.0's
 * `DskProtocolProvenanceSchema`, §1.3-adjacent). Same rule as 0.38.0's
 * `value_frame`/`GoalThresholdFrame` reuse: one vocabulary, N attestation
 * sites — an identity pin in tests/boundary/dsk-claim-provenance-0.39.test.ts
 * REDs if either site is ever replaced by a copy. The domain belongs to the
 * producer's schema (`data/dsk/v1.json`), not to today's data.
 */
export const DskEvidenceStrength = z.enum(['strong', 'medium', 'weak', 'mixed']);
/**
 * 0.39.0 car 1 (ROADMAP 2.964) — DSK CLAIM PROVENANCE. The decision-science
 * CLAIM a coaching card / review card is grounded in, so a consumer can show
 * that the guidance instantiates a cited claim from the DSK bundle rather
 * than assistant prose. The CLAIM sibling of 0.37.0's
 * `DskProtocolProvenanceSchema` (further down this file) — same atomic
 * doctrine, different arm of the bundle id grammar.
 *
 * ⚠ ATOMIC STRICT TRIPLE, NEVER FLAT SIBLINGS — the 0.37.0 comment on
 * `DskProtocolProvenanceSchema` is the doctrine of record (CEE #830: an id
 * must never travel without the title and strength that make it verifiable
 * against `data/dsk/v1.json`; three sibling optionals would let a producer
 * emit a claim id alone — an authority claim with nothing a consumer can
 * check it against). Do not "flatten it for consistency".
 *
 * `claim_id` is `DSKObjectBase.id` (`/^DSK-(B|T|F|G|P|TR)-\d{3}$/`) narrowed
 * to the CLAIM arms — `B` (bias) and `T` (technique) — so a protocol id
 * (`DSK-P-…`) or trigger id (`DSK-TR-…`) cannot masquerade as the claim this
 * card cites. `protocol_id` (optional, INSIDE the object so it can never
 * travel without its claim anchor) additionally names the protocol when the
 * producing hop resolved one.
 *
 * OPTIONAL by design on both carrying blocks (ABSENCE SEMANTICS, for the
 * absence census — distinct): absence means "not grounded in a cited DSK
 * claim" and every surface renders NO grounding badge; presence is an
 * attestation. Absence is never a default, never "unknown claim", and no
 * consumer may infer one. Producers attach it ONLY from bundle-resolved
 * bytes (attested/resolved grounding), never from an LLM's copy of an id —
 * that attach policy is CEE's (ROADMAP 2.964's two-hop map); this schema is
 * the contract precondition.
 */
export const DskClaimProvenanceSchema = z.object({
    claim_id: z.string().regex(/^DSK-(B|T)-\d{3}$/),
    claim_title: z.string().min(1),
    evidence_strength: DskEvidenceStrength,
    protocol_id: z.string().regex(/^DSK-P-\d{3}$/).optional(),
}).strict();
