// §1.2 — CoachingBlock. Produced by the coaching pass (Step 5 of the
// seven-step turn assembly) and draft_graph structured-output threading.
// Hero eligible — `priority_rank` REQUIRED. signal_id REQUIRED;
// graph_hash_at_generation OPTIONAL (draft / pre-analysis blocks may
// pre-date a runnable graph hash).
export const CoachingBlockSchema = z.object({
    // common metadata (§0)
    block_id: z.string().uuid(),
    signal_id: z.string().min(1),
    created_at: z.string().datetime({ offset: true }),
    source_handler: z.string().min(1),
    graph_hash_at_generation: z.string().min(1).optional(),
    freshness: Phase3BlockFreshness,
    // type discriminator
    type: z.literal('coaching'),
    coaching_kind: z.enum([
        'orientation',
        'widening',
        'bias_signal',
        'strengthen',
        'assumption_check',
        'calibration_prompt',
    ]),
    title: z.string().min(1).max(PHASE3_TITLE_MAX),
    body: z.string().min(1).max(PHASE3_BODY_MAX),
    source: z.enum(['draft_graph', 'decision_review', 'deterministic_signal']),
    target_refs: z.array(TargetRefSchema),
    priority_rank: z.number(),
    // 0.19.0 additive (UI-SEM-085) — producer-owned guidance class + coarse
    // urgency score. See the GuidanceCategory block comment for semantics.
    // (CoachingBlock has no `severity` field; `category` is its ONLY
    // producer-owned severity-class signal.)
    category: GuidanceCategory.optional(),
    priority: z.number().min(0).max(100).optional(),
    // 0.20.0 additive (UI-SEM-085 residual) — signal class code + short
    // per-item signal line. See the guidance-signal-provenance block comment.
    // (`signal_code` names the DETECTOR CLASS; `coaching_kind` above stays the
    // block's rendering taxonomy — the housekeeping/rerun nudges 1.120 calls
    // out carry their code here, not by overloading `coaching_kind`.)
    signal_code: z.string().min(1).optional(),
    signal: z.string().min(1).max(GUIDANCE_SIGNAL_LINE_MAX).optional(),
    action_intent: ActionIntent.optional(),
    action_label: z.string().min(1).max(PHASE3_ACTION_LABEL_MAX).optional(),
    /**
     * 0.31.0 additive (ROADMAP 2.225, 1 Aug design note). The PRODUCER-AUTHORED
     * turn text a chip dispatches VERBATIM.
     *
     * WHY THIS EXISTS. `action_intent` names WHAT to do and `action_label` names
     * what the BUTTON SAYS, but neither says what to SEND. So a UI that wants a
     * remedy chip has to compose the turn itself — inventing an interpretation of
     * a signal only the producer understood. The live bias coaching cards are the
     * worked example: they are grounded and they quote the user's own brief, and
     * the UI cannot restate that without paraphrasing evidence it did not
     * generate. This field lets the producer hand over the exact sentence.
     *
     * VERBATIM MEANS VERBATIM. A consumer dispatches this string as the turn
     * text UNMODIFIED — no templating, no interpolation, no appending context,
     * no "improving" it. If a consumer needs to change the wording, the fix
     * belongs at the producer. Rewriting it here re-creates exactly the invented
     * interpretation the field exists to remove.
     *
     * PRODUCER: CEE's coaching pass, alongside `action_intent`/`action_label`.
     * CONSUMER: the UI's coaching-card chip.
     *
     * FAILURE SEMANTICS — FAIL CLOSED, AND SILENTLY. Absence means the producer
     * authored no prompt, and the consumer renders NO dispatching chip. It must
     * not fall back to composing one from `action_intent` or `action_label`:
     * that fallback IS the defect. A card with a label and no prompt is a
     * non-interactive card, which is the honest degradation.
     *
     * ADOPTION SEQUENCING (hazard 1): reader-first is safe and is the intended
     * order — a UI on an older pin drops the key and renders today's
     * non-interactive card, and a UI that adopts before CEE emits simply never
     * sees one. Neither side blocks the other.
     *
     * SCOPE NOTE, STATED SO THE ASYMMETRY IS NOT MISTAKEN FOR AN OVERSIGHT:
     * `ReviewCardBlockSchema` and `EvidenceBlockSchema` also carry
     * `action_intent`/`action_label` and deliberately do NOT get `action_prompt`
     * in 0.31.0. The driving row is about coaching cards; extending it is
     * additive and can ride a later release on evidence of a real producer.
     */
    action_prompt: z.string().min(1).max(PHASE3_ACTION_PROMPT_MAX).optional(),
    // 0.39.0 additive (ROADMAP 2.964) — DSK claim provenance, atomic strict
    // triple. See DskClaimProvenanceSchema above for the full doctrine incl.
    // absence semantics (absent = not grounded in a cited claim, no badge).
    // CEE attaches at the two lineage-bearing mint hops only
    // (calibration_prompt; bias cards gated on 2.965) — attach policy is the
    // producer's, this field is the contract precondition.
    dsk_claim_provenance: DskClaimProvenanceSchema.optional(),
}).strict();
// §1.3 — EvidenceBlock. Produced by the evidence-ranking module
// (`rankEvidenceSources`). Hero eligible — `priority_rank` REQUIRED.
// signal_id REQUIRED; graph_hash_at_generation REQUIRED.
//
// Consistency rule (§1.3): `factor_ref` MUST match the primary factor
// entry in `target_refs`. Enforced at the schema layer via
// `superRefine` on the exported `EvidenceBlockSchema` below (round-3
// review correction — the natural import name now gives the full v1.3
// contract validation). `factor_label` is a backward-compatibility
// convenience; renderers prefer `target_refs[].label` on conflict per
// the contract. The "primary factor entry" is the FIRST entry in
// `target_refs` with `kind: 'factor'` — this admits non-factor refs
// (options / edges / etc.) elsewhere in the array while pinning the
// canonical factor association at the schema boundary.
//
// `EvidenceBlockObjectSchema` (bare ZodObject) is kept as an internal
// helper because `z.discriminatedUnion` only accepts ZodObject members
// (ZodEffects are rejected). It is NOT exported from the package.
const EvidenceBlockObjectSchema = z.object({
    // common metadata (§0)
    block_id: z.string().uuid(),
    signal_id: z.string().min(1),
    created_at: z.string().datetime({ offset: true }),
    source_handler: z.string().min(1),
    graph_hash_at_generation: z.string().min(1),
    freshness: Phase3BlockFreshness,
    // type discriminator
    type: z.literal('evidence'),
    factor_label: z.string().min(1),
    factor_ref: z.object({
        id: z.string().min(1),
        label: z.string().min(1),
        kind: z.literal('factor'),
    }).strict(),
    target_refs: z.array(TargetRefSchema),
    current_confidence: z.enum(['high', 'medium', 'low']),
    evidence_gap: z.string().min(1),
    suggested_technique: z.string().min(1),
    impact_if_gathered: z.string().min(1),
    priority_rank: z.number(),
    severity: Phase3BlockSeverity,
    // 0.19.0 additive (UI-SEM-085) — producer-owned guidance class + coarse
    // urgency score. See the GuidanceCategory block comment for semantics.
    category: GuidanceCategory.optional(),
    priority: z.number().min(0).max(100).optional(),
    // 0.20.0 additive (UI-SEM-085 residual) — signal class code + short
    // per-item signal line. See the guidance-signal-provenance block comment.
    signal_code: z.string().min(1).optional(),
    signal: z.string().min(1).max(GUIDANCE_SIGNAL_LINE_MAX).optional(),
    action_intent: ActionIntent.optional(),
    action_label: z.string().min(1).max(PHASE3_ACTION_LABEL_MAX).optional(),
}).strict();
/**
 * §1.3 consistency rule: factor_ref must match the primary factor
 * entry in target_refs (first entry with `kind: 'factor'`). Applied
 * via `superRefine` on the EXPORTED `EvidenceBlockSchema` so the
 * natural import name gives the full v1.3 contract validator
 * (round-3 review correction — composer code can't silently bypass
 * the rule). Also applied at the discriminated-union level on
 * `BlockSchema` below so wire-level parsing fails closed independently
 * of which entry point the consumer used.
 */
function applyEvidenceConsistencyRule(data, ctx) {
    const primaryFactor = data.target_refs.find((r) => r.kind === 'factor');
    if (!primaryFactor) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['target_refs'],
            message: 'EvidenceBlock target_refs must contain at least one entry with kind="factor" (the primary factor matching factor_ref). Per Analysis tab data contract v1.3 §1.3.',
        });
        return;
    }
    if (primaryFactor.id !== data.factor_ref.id) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['factor_ref', 'id'],
            message: 'EvidenceBlock factor_ref.id must match the primary factor entry in target_refs (first target_refs entry with kind="factor"). Per Analysis tab data contract v1.3 §1.3.',
        });
    }
    if (primaryFactor.label !== data.factor_ref.label) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['factor_ref', 'label'],
            message: 'EvidenceBlock factor_ref.label must match the primary factor entry in target_refs (first target_refs entry with kind="factor"). Per Analysis tab data contract v1.3 §1.3.',
        });
    }
}
/**
 * Public EvidenceBlock schema — full v1.3 contract including the
 * §1.3 consistency rule. The bare ZodObject lives off-export as
 * `EvidenceBlockObjectSchema` for the discriminated-union construction
 * below.
 */
export const EvidenceBlockSchema = EvidenceBlockObjectSchema.superRefine(applyEvidenceConsistencyRule);
/**
 * 0.37.0 — DSK PROTOCOL PROVENANCE. The decision-science record an exercise
 * card is an instance of, so a consumer can show the user that the exercise is
 * a published protocol rather than assistant prose.
 *
 * ⚠ WHY THIS IS ONE NESTED OBJECT AND NOT THREE OPTIONAL SIBLING FIELDS —
 * this is the whole point of the shape, do not "flatten it for consistency".
 * CEE #830 (ROADMAP 2.491/2.456) shipped an attestation that validated a DSK
 * claim id EXISTED without checking that the text rendered beneath it RESOLVED
 * TO that id; the badge printed the model's own prose under the bundle's
 * authority. Three sibling optionals reproduce that shape exactly: a producer
 * could emit `dsk_protocol_id` alone — an authority claim with nothing a
 * consumer can check it against. As ONE strict object the triple is ATOMIC BY
 * CONSTRUCTION: the id never travels without the title and strength that make
 * it verifiable against `data/dsk/v1.json`. No `superRefine` is needed to get
 * that, which matters — `ExerciseBlockSchema` stays a bare `ZodObject`, and
 * CEE's `.shape`-derived egress guard (`leading-option-egress-guard.ts`)
 * depends on it being one.
 *
 * `protocol_id` is the bundle's own id format (`DSKObjectBase.id`,
 * `/^DSK-(B|T|F|G|P|TR)-\d{3}$/`) narrowed to the `P` arm, so a claim id
 * (`DSK-T-…`) or a trigger id (`DSK-TR-…`) cannot masquerade as the protocol
 * this card performs. `evidence_strength` carries the bundle's full declared
 * union — NOT the two values that happen to occur in bundle v1.0.0 — because
 * the domain belongs to the producer's schema, not to today's data.
 *
 * OPTIONAL by design: an exercise whose selection rules predate the bundle
 * (CEE's `pre_mortem` lens) must be able to ship with NO provenance rather
 * than claim one it does not have. Absence means "not attributed", never
 * "unknown protocol".
 */
export const DskProtocolProvenanceSchema = z.object({
    protocol_id: z.string().regex(/^DSK-P-\d{3}$/),
    protocol_title: z.string().min(1),
    evidence_strength: DskEvidenceStrength,
}).strict();
